CREATE TABLE IF NOT EXISTS promo_codes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,uuid CHAR(36) NOT NULL UNIQUE,code VARCHAR(20) NOT NULL UNIQUE,title VARCHAR(80) NOT NULL,reward_type ENUM('wallet_bonus','cashback','fee_discount','free_transfers') NOT NULL,reward_value DECIMAL(18,2) NOT NULL,max_reward DECIMAL(18,2) NULL,min_amount DECIMAL(18,2) NULL,audience ENUM('all','new_users','verified') NOT NULL DEFAULT 'all',usage_limit INT UNSIGNED NULL,per_user_limit INT UNSIGNED NOT NULL DEFAULT 1,status ENUM('active','paused') NOT NULL DEFAULT 'active',starts_at DATETIME NULL,expires_at DATETIME NULL,created_by INT UNSIGNED NULL,updated_by INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES admin_users(id) ON DELETE SET NULL,FOREIGN KEY(updated_by) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS promo_redemptions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,promo_code_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,transaction_id INT UNSIGNED NULL,reward_amount DECIMAL(18,2) NOT NULL DEFAULT 0,currency_code VARCHAR(12) NOT NULL DEFAULT 'NGN',status ENUM('qualified','awarded','reversed') NOT NULL DEFAULT 'qualified',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,awarded_at DATETIME NULL,FOREIGN KEY(promo_code_id) REFERENCES promo_codes(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(transaction_id) REFERENCES transactions(id) ON DELETE SET NULL,INDEX idx_promo_redemptions_code(promo_code_id,status)) ENGINE=InnoDB;
